package io.github.abyxs.codingremote;

import android.content.Context;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

/** One repository state shared by all conversations resolving to its canonical root. */
final class GitPage extends LinearLayout {
    interface Reply {void done(JSONObject result,String error);}
    interface Host {void request(String query,JSONObject body,Reply reply);void back();}
    static final class State {String message="";JSONObject pending;int graphScroll;}
    private final Context context;private final NativeUi ui;private final Host host;private final Map<String,State> states;private final String scope;
    private final LinearLayout changes,graph,toolbar;private final TextView status,heading;private final EditText message;
    private String stateKey="";private JSONObject snapshot;private State state=new State();private boolean working,applying,disposed;private int ticket;
    private TextView branchLabel,changeCount;
    GitPage(Context c,NativeUi u,Host h,Map<String,State> store,String address){super(c);context=c;ui=u;host=h;states=store;scope=address;setOrientation(VERTICAL);setBackgroundColor(NativeUi.CANVAS);setContentDescription("项目 Git 页");
        LinearLayout header=column();header.setBackgroundColor(NativeUi.CANVAS);header.setPadding(ui.dp(10),ui.dp(4),ui.dp(10),ui.dp(12));addView(header);
        LinearLayout top=row();Button back=ui.iconButton("back","返回会话");ui.centerIcon(back,"back",NativeUi.INK,NativeUi.GLYPH_ACTION);top.addView(back,new LayoutParams(ui.dp(48),ui.dp(48)));back.setOnClickListener(v->host.back());heading=ui.text("源代码管理",NativeUi.TITLE,NativeUi.INK);NativeUi.emphasize(heading);heading.setSingleLine();heading.setEllipsize(android.text.TextUtils.TruncateAt.END);top.addView(heading,new LayoutParams(0,-2,1));Button refresh=ui.iconButton("refresh","刷新 Git");ui.centerIcon(refresh,"refresh",NativeUi.INK,NativeUi.GLYPH_ACTION);top.addView(refresh,new LayoutParams(ui.dp(48),ui.dp(48)));refresh.setOnClickListener(v->refresh());header.addView(top);
        status=ui.text("正在读取项目仓库…",NativeUi.CAPTION,NativeUi.MUTED);status.setPadding(ui.dp(12),ui.dp(2),ui.dp(12),ui.dp(4));status.setMaxLines(3);status.setTextIsSelectable(true);header.addView(status);
        LinearLayout upper=column();upper.setPadding(ui.dp(14),ui.dp(10),ui.dp(14),ui.dp(8));addView(upper,new LayoutParams(-1,0,1.1f));
        LinearLayout changesTitle=row();TextView title=ui.text("更改",NativeUi.TITLE,NativeUi.GREEN);NativeUi.emphasize(title);ui.leading(title,"code",NativeUi.GREEN,NativeUi.GLYPH_INLINE);changesTitle.addView(title,new LayoutParams(0,ui.dp(32),1));changeCount=ui.text("",NativeUi.CAPTION,NativeUi.MUTED);changesTitle.addView(changeCount);upper.addView(changesTitle);
        message=new EditText(c);ui.input(message);message.setHint("填写提交说明…");message.setMinLines(1);message.setMaxLines(3);upper.addView(message,new LayoutParams(-1,ui.dp(NativeUi.ROW_TALL)));message.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int n,int f){}public void onTextChanged(CharSequence s,int a,int b,int n){if(!applying){state.message=s.toString();save();}}public void afterTextChanged(android.text.Editable e){}});
        toolbar=row();LayoutParams tools=new LayoutParams(-1,ui.dp(NativeUi.ROW));tools.topMargin=ui.dp(6);upper.addView(toolbar,tools);command(toolbar,"暂存全部",()->stageAll(false));command(toolbar,"取消暂存",()->stageAll(true));command(toolbar,"提交",()->{try{write(new JSONObject().put("operation","commit").put("message",message.getText().toString()));}catch(Exception e){error(e.getMessage());}});
        ScrollView files=new ScrollView(c);files.setContentDescription("Git 文件更改");files.setClipToPadding(false);changes=column();files.addView(changes);upper.addView(files,new LayoutParams(-1,0,1));
        LinearLayout lower=column();lower.setPadding(ui.dp(14),ui.dp(10),ui.dp(14),ui.dp(6));lower.setBackground(ui.surface(NativeUi.SOFT,NativeUi.CORNER_CARD,false));LayoutParams lowerLayout=new LayoutParams(-1,0,1);lowerLayout.leftMargin=ui.dp(6);lowerLayout.rightMargin=ui.dp(6);lowerLayout.bottomMargin=ui.dp(6);addView(lower,lowerLayout);
        LinearLayout graphTitle=row();TextView graphHeading=ui.text("图表",NativeUi.TITLE,NativeUi.GREEN);NativeUi.emphasize(graphHeading);graphTitle.addView(graphHeading,new LayoutParams(0,ui.dp(44),1));Button branch=ui.button("分支",false);branch.setTextColor(NativeUi.INK);branch.setBackground(ui.touch(NativeUi.WHITE,NativeUi.CORNER_ROW,true));graphTitle.addView(branch,new LayoutParams(ui.dp(88),ui.dp(48)));branch.setOnClickListener(v->branches());lower.addView(graphTitle);
        branchLabel=ui.text("",NativeUi.CAPTION,NativeUi.MUTED);branchLabel.setPadding(0,ui.dp(6),0,ui.dp(4));branchLabel.setSingleLine();branchLabel.setEllipsize(android.text.TextUtils.TruncateAt.END);lower.addView(branchLabel);
        LinearLayout remote=row();lower.addView(remote,new LayoutParams(-1,ui.dp(NativeUi.ROW)));for(String[] entry:new String[][]{{"获取","fetch"},{"拉取","pull"},{"推送","push"}})command(remote,entry[0],()->confirmRemote(entry[0],entry[1]));
        ScrollView history=new ScrollView(c);graph=column();history.addView(graph);history.setContentDescription("Git 提交图表");lower.addView(history,new LayoutParams(-1,0,1));history.setOnScrollChangeListener((v,x,y,oldX,oldY)->state.graphScroll=y);
        ui.reveal(this,false);refresh();
    }
    private boolean save(){if(stateKey.isEmpty())return false;try{JSONObject saved=new JSONObject().put("message",state.message).put("pending",state.pending);return context.getSharedPreferences("git-projects",0).edit().putString(stateKey,saved.toString()).commit();}catch(Exception ignored){return false;}}
    private LinearLayout row(){LinearLayout v=new LinearLayout(context);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    private LinearLayout column(){LinearLayout v=new LinearLayout(context);v.setOrientation(VERTICAL);return v;}
    private void command(LinearLayout row,String title,Runnable action){boolean primary=title.equals("提交");Button b=ui.button(title,primary);b.setTextSize(NativeUi.LABEL);b.setPadding(ui.dp(8),0,ui.dp(8),0);if(!primary){b.setBackground(ui.touch(NativeUi.WHITE,NativeUi.CORNER_ROW,true));b.setTextColor(NativeUi.INK);}LayoutParams lp=new LayoutParams(0,ui.dp(48),1);lp.setMargins(ui.dp(4),ui.dp(4),ui.dp(4),ui.dp(4));row.addView(b,lp);b.setOnClickListener(v->{if(!working)action.run();});}
    private void error(String text){status.setText(text);status.setTextColor(NativeUi.RED);}
    void dispose(){disposed=true;ticket++;}
    void refresh(){if(working||disposed)return;int current=++ticket;host.request("",null,(value,error)->{if(current!=ticket)return;if(error!=null){error(error);return;}snapshot=value;String key=scope+"|"+value.optString("projectKey");stateKey=key;state=states.get(key);if(state==null){state=new State();try{JSONObject saved=new JSONObject(context.getSharedPreferences("git-projects",0).getString(key,"{}"));state.message=saved.optString("message");state.pending=saved.optJSONObject("pending");}catch(Exception ignored){}states.put(key,state);}applying=true;message.setText(state.message);applying=false;render();});}
    private void render(){if(snapshot==null)return;heading.setText("源代码管理 · "+snapshot.optString("branch"));status.setText(snapshot.optString("root"));status.setTextColor(NativeUi.MUTED);branchLabel.setText(snapshot.optString("upstream").isEmpty()?"未设置上游分支":snapshot.optString("upstream")+"    ↑ "+snapshot.optInt("ahead")+"    ↓ "+snapshot.optInt("behind"));changes.removeAllViews();
        if(state.pending!=null)renderPending();JSONArray files=snapshot.optJSONArray("files");changeCount.setText((files==null?0:files.length())+" 个文件");
        for(boolean staged:new boolean[]{true,false}){int count=0;for(int i=0;files!=null&&i<files.length();i++){JSONObject f=files.optJSONObject(i);if(f!=null&&included(f,staged))count++;}if(count==0)continue;TextView group=ui.text((staged?"暂存的更改":"工作区更改")+"   "+count,NativeUi.CAPTION,staged?NativeUi.GREEN:NativeUi.MUTED);group.setPadding(ui.dp(10),ui.dp(7),ui.dp(10),ui.dp(7));group.setBackground(ui.surface(staged?NativeUi.TINT:NativeUi.SOFT,NativeUi.CORNER_CHIP,false));LayoutParams groupLayout=new LayoutParams(-1,-2);groupLayout.topMargin=ui.dp(6);groupLayout.bottomMargin=ui.dp(4);changes.addView(group,groupLayout);
            for(int i=0;files!=null&&i<files.length();i++){JSONObject f=files.optJSONObject(i);if(f==null||!included(f,staged))continue;String code=f.optBoolean("untracked")?"U":staged?f.optString("index"):f.optString("worktree");int color=f.optBoolean("conflict")||code.equals("D")?NativeUi.RED:code.equals("U")||code.equals("A")?NativeUi.GREEN:NativeUi.CODE;LinearLayout line=row();line.setBackground(ui.touch(NativeUi.WHITE,NativeUi.CORNER_ROW,false));TextView badge=ui.text(code,NativeUi.CAPTION,color);badge.setGravity(Gravity.CENTER);NativeUi.monospaceStrong(badge);badge.setBackground(ui.surface(NativeUi.SOFT,NativeUi.CORNER_CHIP,false));LayoutParams badgeLayout=new LayoutParams(ui.dp(30),ui.dp(30));badgeLayout.setMargins(ui.dp(4),0,ui.dp(10),0);line.addView(badge,badgeLayout);String path=f.optString("path"),normalized=path.replace('\\','/');int slash=normalized.lastIndexOf('/');LinearLayout labels=column();TextView label=ui.text(slash<0?path:normalized.substring(slash+1),NativeUi.LABEL,NativeUi.INK);label.setSingleLine();label.setEllipsize(android.text.TextUtils.TruncateAt.MIDDLE);labels.addView(label);if(slash>=0){TextView directory=ui.text(normalized.substring(0,slash),NativeUi.CAPTION,NativeUi.MUTED);directory.setSingleLine();directory.setEllipsize(android.text.TextUtils.TruncateAt.MIDDLE);directory.setPadding(0,ui.dp(4),0,0);labels.addView(directory);}labels.setContentDescription("查看差异 "+path);line.addView(labels,new LayoutParams(0,-2,1));labels.setOnClickListener(v->diff(path,staged));Button toggle=ui.iconButton(staged?"close":"plus",(staged?"取消暂存 ":"暂存 ")+path);ui.centerIcon(toggle,staged?"close":"plus",staged?NativeUi.MUTED:NativeUi.GREEN,NativeUi.GLYPH_ACTION);line.addView(toggle,new LayoutParams(ui.dp(48),ui.dp(48)));toggle.setOnClickListener(v->{try{write(new JSONObject().put("operation",staged?"unstage":"stage").put("paths",new JSONArray().put(path)));}catch(Exception e){error(e.getMessage());}});changes.addView(line,new LayoutParams(-1,ui.dp(NativeUi.ROW_TALL)));}}
        if(files==null||files.length()==0){TextView empty=ui.text("工作区干净，所有更改均已提交",NativeUi.LABEL,NativeUi.MUTED);empty.setPadding(ui.dp(8),ui.dp(16),0,ui.dp(16));changes.addView(empty);}
        graph.removeAllViews();JSONArray commits=snapshot.optJSONArray("commits");ArrayList<String> lanes=new ArrayList<>();for(int i=0;commits!=null&&i<commits.length();i++){JSONObject commit=commits.optJSONObject(i);if(commit==null)continue;String hash=commit.optString("hash");int lane=lanes.indexOf(hash);if(lane<0){lane=lanes.size();lanes.add(hash);}ArrayList<String> before=new ArrayList<>(lanes);lanes.remove(lane);JSONArray parents=commit.optJSONArray("parents");for(int n=0;parents!=null&&n<parents.length();n++){String parent=parents.optString(n);if(!lanes.contains(parent))lanes.add(Math.min(lane+n,lanes.size()),parent);}LinearLayout line=row();line.setBackground(ui.touch(i%2==0?NativeUi.WHITE:Color.TRANSPARENT,NativeUi.CORNER_CHIP,false));line.addView(new GraphNode(context,ui,before,new ArrayList<>(lanes),lane,parents),new LayoutParams(ui.dp(Math.min(100,24+Math.max(before.size(),lanes.size())*12)),ui.dp(68)));LinearLayout labels=column();TextView subject=ui.text(commit.optString("subject"),NativeUi.LABEL,NativeUi.INK);subject.setSingleLine();subject.setEllipsize(android.text.TextUtils.TruncateAt.END);labels.addView(subject);TextView detail=ui.text(hash.substring(0,Math.min(7,hash.length()))+" · "+commit.optString("author"),NativeUi.CAPTION,NativeUi.MUTED);detail.setSingleLine();detail.setPadding(0,ui.dp(4),0,0);labels.addView(detail);if(!commit.optString("refs").isEmpty()){TextView refs=ui.text(commit.optString("refs"),NativeUi.CAPTION,NativeUi.GREEN);refs.setSingleLine();refs.setPadding(0,ui.dp(3),0,0);labels.addView(refs);}line.addView(labels,new LayoutParams(0,-2,1));line.setOnClickListener(v->new NativeDialogBuilder(context,ui).setTitle(commit.optString("subject")).setMessage(hash+"\n"+commit.optString("author")+"\n"+commit.optString("date")+"\n"+commit.optString("refs")).setPositiveButton("关闭",null).show());graph.addView(line);}
        if(commits==null||commits.length()==0)graph.addView(ui.text("尚无提交，暂存更改后创建首次提交",NativeUi.LABEL,NativeUi.MUTED));ScrollView history=(ScrollView)graph.getParent();history.post(()->history.scrollTo(0,state.graphScroll));
    }
    private boolean included(JSONObject file,boolean staged){return staged?!file.optString("index").equals(" ")&&!file.optBoolean("untracked"):!file.optString("worktree").equals(" ");}
    private void stageAll(boolean staged){if(snapshot==null)return;JSONArray selected=new JSONArray(),files=snapshot.optJSONArray("files");for(int i=0;files!=null&&i<files.length();i++)if(included(files.optJSONObject(i),staged))selected.put(files.optJSONObject(i).optString("path"));if(selected.length()==0){error("没有可操作的文件");return;}try{write(new JSONObject().put("operation",staged?"unstage":"stage").put("paths",selected));}catch(Exception e){error(e.getMessage());}}
    private void diff(String path,boolean staged){if(working)return;int current=ticket;host.request("?path="+android.net.Uri.encode(path)+"&staged="+staged,null,(value,error)->{if(current!=ticket)return;if(error!=null){error(error);return;}LinearLayout body=column();new MessageContent(context,ui).code(body,value.optString("diff").isEmpty()?"没有文本差异":value.optString("diff"),"diff");ScrollView scroll=new ScrollView(context);scroll.addView(body);new NativeDialogBuilder(context,ui).setTitle(path).setView(scroll).setPositiveButton("关闭",null).show();});}
    private void write(JSONObject request){if(working||snapshot==null)return;if(state.pending!=null&&request!=state.pending){error("请先核对上次 Git 操作");return;}try{if(!request.has("id"))request.put("id",UUID.randomUUID().toString());}catch(Exception e){return;}JSONObject previous=state.pending;state.pending=request;if(!save()){state.pending=previous;error("无法保存操作回执，请检查手机存储后重试");return;}working=true;status.setText("正在执行 Git 操作…");host.request("",request,(result,error)->{working=false;if(error!=null){if(!disposed){error(error+"；可核对原请求");renderPending();}return;}String outcome=result.optString("status");if(outcome.equals("accepted")||outcome.equals("rejected")){state.pending=null;if(outcome.equals("accepted")&&request.optString("operation").equals("commit"))state.message="";save();if(!disposed){refresh();Toast.makeText(context,result.optString("message"),Toast.LENGTH_LONG).show();}}else if(!disposed){error(result.optString("message"));renderPending();}});}
    private void renderPending(){View old=changes.findViewWithTag("git-receipt");if(old!=null)changes.removeView(old);LinearLayout receipt=row();receipt.setTag("git-receipt");changes.addView(receipt,0,new LayoutParams(-1,ui.dp(48)));command(receipt,"核对上次 Git 操作",()->write(state.pending));command(receipt,"已核对结果",()->new NativeDialogBuilder(context,ui).setTitle("解除待核对状态？").setMessage("请先查看文件与提交图表，确认上次操作的实际结果。解除后可以执行新的 Git 操作。").setNegativeButton("取消",null).setPositiveButton("已核对",(d,w)->{JSONObject pending=state.pending;state.pending=null;if(!save()){state.pending=pending;error("无法保存核对结果");return;}refresh();}).show());}
    private void confirmRemote(String label,String operation){if(snapshot==null)return;new NativeDialogBuilder(context,ui).setTitle(label).setMessage(snapshot.optString("root")+"\n"+snapshot.optString("branch")+" → "+snapshot.optString("upstream","默认远程")+(operation.equals("pull")?"\n仅允许快进合并":"")).setNegativeButton("取消",null).setPositiveButton(label,(d,w)->{try{write(new JSONObject().put("operation",operation).put("confirmed",true));}catch(Exception e){error(e.getMessage());}}).show();}
    private void branches(){if(snapshot==null||working)return;JSONArray values=snapshot.optJSONArray("branches");String[] names=new String[(values==null?0:values.length())+1];names[0]="新建分支…";for(int i=1;i<names.length;i++)names[i]=values.optString(i-1);new NativeDialogBuilder(context,ui).setTitle("切换分支").setItems(names,(d,which)->{if(which==0){EditText input=new EditText(context);input.setSingleLine();input.setHint("新分支名称");new NativeDialogBuilder(context,ui).setTitle("新建并切换分支").setView(input).setNegativeButton("取消",null).setPositiveButton("创建",(a,b)->branch("branch",input.getText().toString())).show();}else branch("switch",names[which]);}).show();}
    private void branch(String operation,String name){try{write(new JSONObject().put("operation",operation).put("branch",name));}catch(Exception e){error(e.getMessage());}}
    static final class GraphNode extends View {
        final Paint paint=new Paint(3);final NativeUi ui;final ArrayList<String> before,after;final int lane;final JSONArray parents;
        GraphNode(Context c,NativeUi u,ArrayList<String>b,ArrayList<String>a,int l,JSONArray p){super(c);ui=u;before=b;after=a;lane=l;parents=p;}
        float x(int n){return ui.dp(12+Math.min(7,n)*12);}
        protected void onDraw(Canvas c){float middle=getHeight()/2f;paint.setStrokeWidth(ui.dp(2));int[] colors={NativeUi.GREEN,NativeUi.CODE,NativeUi.KEYWORD,NativeUi.EMPHASIS};for(int i=0;i<before.size();i++){paint.setColor(colors[i%colors.length]);if(i==lane)c.drawLine(x(i),0,x(i),middle,paint);else{int end=after.indexOf(before.get(i));if(end>=0)c.drawLine(x(i),0,x(end),getHeight(),paint);}}for(int n=0;parents!=null&&n<parents.length();n++){int end=after.indexOf(parents.optString(n));if(end>=0){paint.setColor(colors[lane%colors.length]);c.drawLine(x(lane),middle,x(end),getHeight(),paint);}}paint.setColor(colors[lane%colors.length]);c.drawCircle(x(lane),middle,ui.dp(4),paint);}
    }
}
